<script lang="ts">
 import {onMount} from 'svelte';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {PublishingGateway,Revision} from '../application/publishing';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 import {AppFailure} from '$lib/shared/domain/failure';
 import {publicationReleaseId} from '../domain/release-link';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 let {user,gateway}:{user:Account|null;gateway:PublishingGateway}=$props();const {locale}=useLocale();
 let items=$state<Revision[]>([]),loading=$state(true),busy=$state(false),more=$state(false),error=$state(''),notice=$state(''),selected=$state(''),reason=$state(''),releaseLink=$state(''),withdrawReason=$state(''),published=$state('');
 const allowed=$derived(user?.role==='admin'||user?.role==='moderator');
 async function load(append=false){const batch=await gateway.pending(append?items.length:0);items=append?[...items,...batch]:batch;more=batch.length===100;}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{if(!allowed){loading=false;return;}void run(async()=>{try{await load();}finally{loading=false;}});});
 async function review(item:Revision,decision:'publish'|'reject'){await run(async()=>{await gateway.review(item.id,decision,decision==='reject'?reason:'');selected='';reason='';await load();if(decision==='publish'){published=item.releaseId;notice=text($locale,'Тарау жарияланды.','Глава опубликована.');}else{published='';notice=text($locale,'Тарау себеппен қайтарылды.','Глава возвращена с причиной.');}});}
 async function withdraw(event:SubmitEvent){event.preventDefault();await run(async()=>{const releaseId=publicationReleaseId(releaseLink,window.location.origin);if(!releaseId)throw new AppFailure('validation');await gateway.withdraw(releaseId,withdrawReason);releaseLink='';withdrawReason='';notice=text($locale,'Жарияланым оқудан алынды.','Публикация снята с чтения.');});}
</script>
<svelte:head><title>{text($locale,'Жарияланымдарды тексеру','Проверка публикаций')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={text($locale,'Жарияланымдар','Публикации')} description={text($locale,'Читалкада тексер, деректерін салыстыр, содан кейін шешім қабылда.','Проверь главу в читалке и её сведения, затем прими решение.')}/>
{#if !allowed}<p>{text($locale,'Модератор рұқсаты қажет.','Нужен доступ модератора.')}</p>{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}
 {#if notice}<p role="status" class="form-message success">{notice}</p>{#if published}<a class="button subtle" href={'/read/'+published}>{text($locale,'Жарияланған тарауды ашу','Открыть опубликованную главу')}</a>{/if}{/if}
 {#if loading}<p role="status">{text($locale,'Жарияланымдар жүктелуде…','Загружаем публикации…')}</p>{:else}
 {#each items as item}<article><div class="heading"><div><h2>{item.titleName}</h2><p class="muted">{text($locale,item.chapterLabel+'-тарау','Глава '+item.chapterLabel)} · {item.teamName}</p></div><a class="button subtle" href={'/read/'+item.releaseId+'?preview='+item.id}>{text($locale,'Тексеріп оқу','Проверить в читалке')}</a></div>
 <details><summary>{text($locale,'Дереккөз, кредиттер және құқықтар','Источник, кредиты и права')}</summary><dl><dt>{text($locale,'Дереккөз және құқық негізі','Источник и основание прав')}</dt><dd>{item.source||'—'}</dd><dt>{text($locale,'Кредиттер','Кредиты')}</dt><dd>{item.credits||'—'}</dd><dt>{text($locale,'Растау','Подтверждение')}</dt><dd>{item.rightsConfirmed?text($locale,'Расталған','Подтверждено'):text($locale,'Расталмаған — жариялауға болмайды','Не подтверждено — публикация запрещена')}</dd></dl></details>
 <div class="actions"><button class="button primary" disabled={busy||!item.rightsConfirmed} onclick={()=>review(item,'publish')}>{text($locale,'Жариялау','Опубликовать')}</button><button class="button subtle" disabled={busy} onclick={()=>{selected=item.id;reason='';}}>{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</button></div>
 {#if selected===item.id}<form onsubmit={event=>{event.preventDefault();void review(item,'reject');}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} required minlength="8" maxlength="2000" rows="3"></textarea></label><div class="actions"><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button><button type="button" class="button subtle" onclick={()=>selected=''}>{text($locale,'Бас тарту','Отмена')}</button></div></form>{/if}
 </article>{:else}{#if !error}<div class="empty-state"><h2>{text($locale,'Тексерілетін тарау жоқ','Нет глав на проверке')}</h2><p>{text($locale,'Командалар жіберген дайын нұсқалар осында пайда болады.','Здесь появятся готовые версии, отправленные командами.')}</p></div>{/if}{/each}
 {#if more}<button class="button subtle" disabled={busy} onclick={()=>run(()=>load(true))}>{text($locale,'Тағы жарияланымдар','Ещё публикации')}</button>{/if}
 {/if}
 <details class="withdraw"><summary>{text($locale,'Жарияланған тарауды оқудан алу','Снять опубликованную главу')}</summary><p class="muted">{text($locale,'Бұл тарау читалкада ашылмайды. Сілтемесі мен себебін тексер.','Глава станет недоступна в читалке. Проверь ссылку и укажи причину.')}</p><form onsubmit={withdraw}><label>{text($locale,'Осы сайттағы тарау сілтемесі','Ссылка на главу этого сайта')}<input bind:value={releaseLink} required placeholder="/read/…"/></label><label>{text($locale,'Оқудан алу себебі','Причина снятия')}<textarea bind:value={withdrawReason} required minlength="8" maxlength="2000" rows="3"></textarea></label><button class="button subtle" disabled={busy}>{text($locale,'Оқудан алуды растау','Подтвердить снятие')}</button></form></details>
{/if}
<style>article{max-width:940px;padding:24px 0;border-bottom:1px solid var(--line)}.heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.heading>div{min-width:0}h2{font-size:20px;margin:0;overflow-wrap:anywhere}.muted{font-size:14px;color:var(--muted);line-height:1.6}details{max-width:800px}summary{min-height:48px;display:flex;align-items:center;cursor:pointer;font-size:14px}dt{font-size:13px;color:var(--muted)}dd{margin:8px 0 16px;white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}form{display:grid;gap:16px;max-width:640px;margin:20px 0}label{display:grid;gap:8px;font-size:14px}form>.button{justify-self:start}.withdraw{margin-top:32px;border-top:1px solid var(--line);padding-top:8px}</style>
